const _dash=VIEWS.dashboard; VIEWS.dashboard=function(){
  vaultEnsureCss();
  const html=_dash();
  const live=db.orders.filter(o=>o.status!=='completed'&&o.status!=='cancelled');
  const held=r2(live.reduce((s,o)=>s+orderPaid(o),0));
  const outstanding=r2(live.reduce((s,o)=>s+Math.max(0,orderBalance(o)),0));
  const recog=r2(db.orders.filter(o=>o.status==='completed').reduce((s,o)=>s+totals(o).total,0)+db.orders.filter(o=>o.status==='cancelled').reduce((s,o)=>s+(+o.cancelFee||0),0));
  const cash=r2(db.orders.reduce((s,o)=>s+orderPaid(o),0)); /* every dollar taken in, cancellations included */
  const shop=live.filter(o=>o.status==='in_progress'), ready=live.filter(o=>o.status==='ready');
  const spec=live.filter(o=>isSpecial(o));
  const oldest=live.length?Math.max.apply(null,live.map(o=>Math.max(0,Math.floor((Date.now()-(o.createdAt||Date.now()))/86400000)))):0;
  const balanced=Math.abs(r2(cash-recog-held))<0.01;
  const P=(n)=>{ const dec=Math.abs(n%1)>0.001; return luxParts(n,dec); };
  const cell=(view,lab,val,sub,n)=>'<div class="v-cell" data-act="go" data-view="'+view+'">'+
    '<div class="v-lab">'+lab+(n===undefined?'':'<b>'+n+'</b>')+'</div><div class="v-val">'+P(val)+'</div>'+
    '<div class="v-sub">'+esc(sub)+'</div></div>';
  /* second tier: the estimate + invoice book, folded into the same panel */
  const bk=window.DASHBOOK||null;
  const cell2=(o)=>'<div class="v2-cell'+(o.warn?' warn':'')+'" data-act="goChip" data-view="'+o.view+'" data-chip="'+o.chip+'">'+
    '<div class="v-lab">'+o.lab+'<b>'+o.n+'</b></div><div class="v2-val">'+P(o.val)+'</div>'+
    '<div class="v2-foot"><span class="v-sub">'+esc(o.sub)+'</span><span class="v-go">Open <i class="fa-solid fa-arrow-right-long"></i></span></div></div>';
  const tier2 = bk ? ('<div class="v2">'+
      cell2({lab:'Open estimates',n:bk.openQ.length,val:bk.sum(bk.openQ,q=>totals(q).total),view:'quotes',chip:'open',
             sub:bk.openQ.length?('oldest waiting '+bk.oldestQ+' day'+(bk.oldestQ===1?'':'s')):'nothing waiting on a client'})+
      cell2({lab:'Accepted',n:bk.accQ.length,val:bk.sum(bk.accQ,q=>totals(q).total),view:'quotes',chip:'accepted',
             sub:bk.accQ.length?(bk.accQ.length+' ready to convert'):'none awaiting conversion'})+
      cell2({lab:'Open invoices',n:bk.openI.length,val:bk.sum(bk.openI,i=>balance(i)),view:'invoices',chip:'open',
             sub:bk.dueSoon?(bk.dueSoon+' due within 7 days'):'nothing due this week'})+
      cell2({lab:'Overdue',n:bk.overI.length,val:bk.sum(bk.overI,i=>balance(i)),view:'invoices',chip:'overdue',warn:!!bk.overI.length,
             sub:bk.overI.length?(bk.overI.length+' past the due date'):'every invoice is current'})+
    '</div>') : '';
  const band='<section class="vault"><span class="tick bl"></span><span class="tick br"></span>'+
    '<div class="vault-top">'+
      '<div class="vault-hero" data-act="go" data-view="orders">'+
        '<div class="v-lab">Deposits held<b>'+live.length+' open</b></div>'+
        '<div class="v-hero-val">'+P(held)+'</div>'+
        '<div class="v-cap">Client money sitting on open work — not revenue until the piece is collected.'+(oldest?' Oldest open job '+oldest+' days.':'')+'</div>'+
      '</div>'+
      '<div class="v-grid">'+
        cell('orders','Still to collect',outstanding,live.length+' job'+(live.length===1?'':'s')+' with a balance')+
        cell('payments','Recognised revenue',recog,'earned on completed work')+
        cell('orders','In the workshop',shop.reduce((s,o)=>s+totals(o).total,0),shop.length?(shop.length+' being worked on'):'nothing on the bench',shop.length)+
        cell('orders','Ready for pickup',ready.reduce((s,o)=>s+totals(o).total,0),ready.length?(ready.length+' waiting on the client'):'nothing waiting',ready.length)+
      '</div>'+
    '</div>'+
    tier2+
    '<div class="vault-foot">'+
      '<span>Cash received <span class="eq">'+money(cash)+'</span></span><span class="sep">=</span>'+
      '<span>Recognised <span class="eq">'+money(recog)+'</span></span><span class="sep">+</span>'+
      '<span>Held unearned <span class="eq">'+money(held)+'</span></span>'+
      '<span class="'+(balanced?'ok':'bad')+'" style="margin-left:auto">'+(balanced?'Books balance':'Out by '+money(r2(cash-recog-held)))+'</span>'+
      (spec.length?'<span class="sep">·</span><span>'+spec.length+' special order'+(spec.length===1?'':'s')+' on the floor</span>':'')+
    '</div>'+
  '</section>';
  const SKEL='<div id="svc-metrics"><div class="vault-skel" aria-hidden="true"></div></div>';
  if(html.indexOf(SKEL)>-1) return html.replace(SKEL, band);
  if(html.indexOf('<div id="svc-metrics"></div>')>-1) return html.replace('<div id="svc-metrics"></div>', band);
  return html.replace('<section class="lux-actions">', band+'<section class="lux-actions">');
};
/* payments view: reconciliation table */
const _payView=VIEWS.payments; VIEWS.payments=function(){
  const html=_payView();
  const rows=db.orders.slice().sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).map(o=>{ const t=totals(o).total; const ps=orderPays(o); const dep=r2(ps.filter(p=>p.kind==='deposit').reduce((s,p)=>s+p.amount,0)); const fin=r2(ps.filter(p=>p.kind==='final').reduce((s,p)=>s+p.amount,0)); const ref=r2(ps.filter(p=>p.kind==='refund').reduce((s,p)=>s+p.amount,0)); const cash=r2(dep+fin+ref); const recog=o.status==='completed'?t:(o.status==='cancelled'?(+o.cancelFee||0):0); const liab=(o.status==='completed'||o.status==='cancelled')?0:cash; const bal=o.status==='cancelled'?0:r2(t-cash);
    return {o,t,dep,fin,ref,cash,recog,liab,bal}; });
  const tot=rows.reduce((a,r)=>{a.t+=r.t;a.dep+=r.dep;a.fin+=r.fin;a.ref+=r.ref;a.cash+=r.cash;a.recog+=r.recog;a.liab+=r.liab;a.bal+=r.bal;return a;},{t:0,dep:0,fin:0,ref:0,cash:0,recog:0,liab:0,bal:0});
  const tbl='<div class="card" style="margin-top:22px"><div class="panel"><h3>Service deposit reconciliation</h3><p class="mut sm" style="margin-bottom:10px">Per job: value, deposits, final payment, refunds, cash received, recognised sales (only completed / cancellation fees), unearned-revenue liability (deposits held on open services) and remaining balance. Must reconcile: cash = recognised + liability + refunds-netted.</p>'+
  '<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Order</th><th>Status</th><th>Lightspeed</th><th class="r">Service value</th><th class="r">Deposits</th><th class="r">Final</th><th class="r">Refunds</th><th class="r">Cash received</th><th class="r">Recognised</th><th class="r">Liability</th><th class="r">Balance</th></tr></thead><tbody>'+
  rows.map(r=>'<tr class="rowlink" data-act="open" data-type="order" data-id="'+r.o.id+'"><td class="num">'+esc(r.o.number)+'</td><td>'+badge(OB,r.o.status)+'</td><td>'+esc(LS_STATUS_LABEL(r.o.ls))+(r.o.ls.receipt?' #'+esc(r.o.ls.receipt):'')+'</td><td class="r">'+money(r.t)+'</td><td class="r">'+money(r.dep)+'</td><td class="r">'+money(r.fin)+'</td><td class="r">'+money(r.ref)+'</td><td class="r">'+money(r.cash)+'</td><td class="r">'+money(r.recog)+'</td><td class="r">'+money(r.liab)+'</td><td class="r">'+money(r.bal)+'</td></tr>').join('')+
  '<tr style="font-weight:700"><td colspan="3">Totals</td><td class="r">'+money(tot.t)+'</td><td class="r">'+money(tot.dep)+'</td><td class="r">'+money(tot.fin)+'</td><td class="r">'+money(tot.ref)+'</td><td class="r">'+money(tot.cash)+'</td><td class="r">'+money(tot.recog)+'</td><td class="r">'+money(tot.liab)+'</td><td class="r">'+money(tot.bal)+'</td></tr></tbody></table></div>'+
  '<div class="actrow" style="margin-top:8px"><button class="b2 o" data-act="csv" data-kind="reconciliation"><i class="fa-solid fa-download"></i> Reconciliation CSV</button></div></div></div>';
  return html+tbl;
};
const _csv=ACT.csv; ACT.csv=d=>{ if(d.kind==='reconciliation'){ const rows=[['Order','Status','Lightspeed','Sale id','Service value','Deposits','Final','Refunds','Cash received','Recognised','Liability','Balance']].concat(db.orders.map(o=>{ const t=totals(o).total; const ps=orderPays(o); const dep=r2(ps.filter(p=>p.kind==='deposit').reduce((s,p)=>s+p.amount,0)); const fin=r2(ps.filter(p=>p.kind==='final').reduce((s,p)=>s+p.amount,0)); const ref=r2(ps.filter(p=>p.kind==='refund').reduce((s,p)=>s+p.amount,0)); const cash=r2(dep+fin+ref); const recog=o.status==='completed'?t:(o.status==='cancelled'?(+o.cancelFee||0):0); const liab=(o.status==='completed'||o.status==='cancelled')?0:cash; return [o.number,o.status,LS_STATUS_LABEL(o.ls),o.ls.saleId||'',t,dep,fin,ref,cash,recog,liab,o.status==='cancelled'?0:r2(t-cash)]; })); csvOut('reconciliation-'+todayISO()+'.csv',rows); return; }
  if(d.kind==='audit'){ csvOut('audit-'+todayISO()+'.csv',[['When','User','Action','Entity','EntityId','Detail']].concat((db.audit||[]).map(a=>[new Date(a.at).toISOString(),a.userName,a.action,a.entity,a.entityId,a.detail]))); return; }
  if(d.kind==='payments'){ csvOut('payments-'+todayISO()+'.csv',[['Number','Date','When','Kind','Contact','Order','Invoice','Method','Amount','Processed by','Lightspeed sync','LS payment id']].concat(db.payments.map(p=>{ const o=p.orderId?O(p.orderId):null; const inv=p.invoiceId?I(p.invoiceId):null; return [p.number,p.date,new Date(p.at).toISOString(),p.kind,cname(p.contactId),o?o.number:'',inv?inv.number:'',p.method,p.amount,p.userName||'',p.sync||'',p.lsPaymentId||'']; }))); return; }
  _csv(d); };
/* orders list: show LS + balance columns */
