function importLsPayments(o, d){
  if(!d || !Array.isArray(d.payments) || !d.payments.length) return 0;
  /* a Lightspeed payment id can only ever belong to one record anywhere in the book */
  const known=new Set((db.payments||[]).map(p=>String(p.lsPaymentId||'')).filter(Boolean));
  orderPays(o).forEach(p=>known.add(String(p.lsPaymentId||p.id)));
  let added=0;
  d.payments.forEach(lp=>{
    const lid=String(lp.id||''); if(!lid||known.has(lid)) return;
    const cfg=(lp.type&&(lp.type.config_id||lp.type.id))||null;
    const name=(lp.type&&lp.type.name)||'Register payment';
    const p={id:uuid(), number:'PAY-'+pad4(db.counters.payment++), kind:'deposit', orderId:o.id, invoiceId:(db.invoices.find(i=>i.orderId===o.id)||{}).id||null, contactId:o.contactId, amount:r2(+lp.amount||0), method:name, date:((lp.date||'').slice(0,10))||todayISO(), note:'Taken at the Lightspeed register', at:(lp.date?Date.parse(lp.date):Date.now())||Date.now(), userId:null, userName:'Lightspeed register', opId:null, lsPaymentId:lid, lsTypeConfigId:cfg, sync:'posted', error:null, source:'register'};
    db.payments.push(p); known.add(lid); added++;
    audit('payment.imported_from_register','order',o.id,{number:p.number, amount:p.amount, method:name});
  });
  /* premature close: the register force-completes a sale when the FULL amount is tendered
     (Layaway is not offered at $0 balance — platform behaviour). An unreceived special must not
     sit in Lightspeed as a completed sale, so this check runs on EVERY refresh — even when the
     payment was already imported on an earlier pull. */
  /* Paying in full is not collecting. The register force-completes a sale the moment the balance
     reaches zero — that is the platform deciding a tender is finished, not anybody saying the
     client has the piece. A watch paid for in full is still on the bench until someone hands it
     over, so a sale the register closed is premature for EVERY kind of job, special order or
     service, received or not. The only thing that recognises revenue is Complete & close in this
     app, which is a person saying the client walked out with it. */
  const premature = d.state==='closed' && o.status!=='completed' && o.status!=='cancelled';
  if(premature) setTimeout(function(){ reopenPrematureClose(o); },0);
  if(added){
    if(orderBalance(o)<=0.004){ const ps=orderPays(o).filter(p=>p.source==='register'); if(ps.length) ps[ps.length-1].kind='final'; }
    if(o.ls) o.ls.expectAtRegister=null;
    logAct('cash-register','Lightspeed',[{t:added+' register payment(s) imported for '},{l:o.number,v:'order',id:o.id},{t:' — held unearned '+money(orderPaid(o))}],null);
    if(orderBalance(o)<=0.004 && o.status!=='completed' && o.status!=='cancelled'){
      audit('payment.paid_in_full_not_recognised','order',o.id,'paid in full at the register — held as unearned revenue until Complete & close');
      toast(o.number+' is paid in full. It stays unearned until you press Complete & close at pickup.', 7000);
    }
    commit();
  }
  return added;
}
let __pullBusy=false;
async function maybeAutoPull(id){
  if(__pullBusy) return; const o=O(id); if(!o) return;
  if(!(o.ls&&o.ls.saleId&&o.ls.created)) return;
  if(o.status==='completed'||o.status==='cancelled') return;
  if(!LS.connected()) return;
  const now=Date.now(); if(o.ls.lastAutoPull && now-o.ls.lastAutoPull<20000) return;
  o.ls.lastAutoPull=now; __pullBusy=true;
  try{ const before=orderPays(o).length; await LS.refreshSale(o); if(orderPays(o).length!==before){ render(); toast('Payment taken at the Lightspeed register has been added to '+o.number); } }
  catch(e){ /* quiet */ }
  finally{ __pullBusy=false; }
}
