    chips.push('<span class="kchip">'+esc((x.loc||'').split(' ')[0])+'</span>');
    if(x.status==='open') chips.push('<span class="kchip'+(age>=5?' red':'')+'">Sent '+age+'d</span>');
    if(x.status==='accepted') chips.push('<span class="kchip green">Signed</span>');
